                completedNi = workStack.pop()
                result = completedNi
                i += 1
            else:
                sb = ''
                while i < len(s) and (s[i].isdigit() or s[i] == '-'):
                    sb += s[i]
                    i += 1
                num = int(sb)
                if workStack:
                    ni = workStack.pop()
                else:
                    ni = NestedInteger()
